+        let chords: Vec<(Point2, Point2)> = path
+            .moves
+            .iter()
+            .filter(|m| m.kind != MoveKind::Rapid && (m.from.z - z).abs() < 1e-9 && (m.to.z - z).abs() < 1e-9)
